WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS RankByScore FROM Posts AS p WHERE NOT (p.Score IS NULL) AND p.CreationDate >= CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '1' YEAR), PostVoteSummary AS (SELECT pv.PostId, SUM(CASE WHEN vt.Name = 'UpMod' THEN 1 ELSE 0 END) AS UpVoteCount, SUM(CASE WHEN vt.Name = 'DownMod' THEN 1 ELSE 0 END) AS DownVoteCount FROM Votes AS pv JOIN VoteTypes AS vt ON pv.VoteTypeId = vt.Id GROUP BY pv.PostId), PostCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.CreationDate, rp.Score, COALESCE(pvs.UpVoteCount, 0) AS UpVoteCount, COALESCE(pvs.DownVoteCount, 0) AS DownVoteCount, COALESCE(pcr.CloseReasons, 'Not Closed') AS CloseReasons, CASE WHEN rp.RankByScore <= 3 THEN 'Top Post' ELSE 'Regular Post' END AS PostCategory FROM RankedPosts AS rp LEFT JOIN PostVoteSummary AS pvs ON rp.PostId = pvs.PostId LEFT JOIN PostCloseReasons AS pcr ON rp.PostId = pcr.PostId WHERE rp.RankByScore <= 5 ORDER BY rp.Score DESC NULLS FIRST